package com.jnapanam.sportszone.commerce.service;
import static com.jnapanam.sportszone.commerce.dto.CommerceDtos.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class CommerceAdminService{private final JdbcTemplate jdbc;public CommerceAdminService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public UUID category(CategoryRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into commerce_categories(id,code,name,name_kn,description,image_url,display_order) values(?,?,?,?,?,?,?)",id,r.code().toUpperCase(),r.name(),r.nameKn(),r.description(),r.imageUrl(),r.displayOrder());return id;}
 public UUID product(ProductRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into commerce_products(id,category_id,sku,name,name_kn,description,description_kn,image_url,tax_percent,status) values(?,?,?,?,?,?,?,?,?,?)",id,r.categoryId(),r.sku().toUpperCase(),r.name(),r.nameKn(),r.description(),r.descriptionKn(),r.imageUrl(),r.taxPercent(),r.status()==null?"DRAFT":r.status().toUpperCase());return id;}
 public UUID variant(UUID product,VariantRequest r){UUID id=UUID.randomUUID();jdbc.update("insert into commerce_variants(id,product_id,sku,label,price_paise,stock_quantity,low_stock_threshold) values(?,?,?,?,?,?,?)",id,product,r.sku().toUpperCase(),r.label(),r.pricePaise(),r.stockQuantity(),r.lowStockThreshold());return id;}
 @Transactional public void stock(UUID actor,UUID variant,StockRequest r){Integer changed=jdbc.queryForObject("update commerce_variants set stock_quantity=stock_quantity+? where id=? and stock_quantity+?>=0 returning stock_quantity",Integer.class,r.quantityDelta(),variant,r.quantityDelta());if(changed==null)throw new IllegalArgumentException("Stock adjustment would make inventory negative");jdbc.update("insert into commerce_stock_movements(variant_id,quantity_delta,reason,actor_id) values(?,?,?,?)",variant,r.quantityDelta(),r.reason(),actor);}
 public void orderStatus(UUID id,String status){String s=status.toUpperCase();if(!Set.of("PLACED","CONFIRMED","PACKED","READY_FOR_PICKUP","SHIPPED","DELIVERED","CANCELLED").contains(s))throw new IllegalArgumentException("Unsupported order status");if(jdbc.update("update commerce_orders set status=?,updated_at=now() where id=?",s,id)==0)throw new IllegalArgumentException("Order not found");}
 public List<Map<String,Object>> orders(){return jdbc.queryForList("select id,order_number,status,fulfilment_type,payment_method,payment_status,total_paise,recipient_name,mobile,created_at from commerce_orders order by created_at desc");}
}
